FILES = {'lc/__init__.py': '', 'lc/data.py': '"""Load the competition CSVs into Case objects."""\nimport csv\nimport os\nimport re\nfrom dataclasses import dataclass, field\n\nDATA_DIR = os.environ.get("LC_DATA_DIR", "data")\nMSG_RE = re.compile(r"^\\s*(\\d+)\\.\\s*([ABCD]):\\s*(.*?)\\s*$")\n\n\n@dataclass\nclass Message:\n    num: int\n    label: str\n    text: str\n\n\n@dataclass\nclass Case:\n    id: str\n    scenario: str\n    speakers: dict  # label -> name\n    evidence: str\n    messages: list\n    label: str = None  # train only\n    extra: dict = field(default_factory=dict)\n\n    @property\n    def names(self):\n        return {v: k for k, v in self.speakers.items()}  # name -> label\n\n\ndef parse_speakers(s):\n    out = {}\n    for part in s.split(";"):\n        k, v = part.split("=", 1)\n        out[k.strip()] = v.strip()\n    return out\n\n\ndef parse_chat(chat):\n    msgs = []\n    for line in chat.strip().splitlines():\n        m = MSG_RE.match(line)\n        if not m:\n            raise ValueError(f"bad chat line: {line!r}")\n        msgs.append(Message(int(m.group(1)), m.group(2), m.group(3)))\n    return msgs\n\n\ndef load(split, data_dir=None):\n    path = os.path.join(data_dir or DATA_DIR, f"{split}.csv")\n    with open(path, encoding="utf-8", newline="") as f:\n        rows = list(csv.DictReader(f))\n    return [\n        Case(r["id"], r["scenario"], parse_speakers(r["speakers"]), r["evidence"], parse_chat(r["chat"]), r.get("label"))\n        for r in rows\n    ]\n', 'lc/llm/__init__.py': '', 'lc/llm/prompt.py': '"""The judge prompt: the competition\'s rules, one case, and the answer format."""\n\nRULES = """\\\nYou will read a group chat and some verified evidence. Exactly one speaker sent a message that cannot be true together with the evidence. Find that speaker.\n\nRules:\n- Only the evidence and the speaker table are true. Chat messages are claims, and one speaker\'s claim never proves another speaker wrong.\n- A claim contradicts the evidence only if it cannot be true at the same time as the evidence, using the literal meaning of the words, basic logic, and clock and calendar arithmetic.\n- A claim that is merely unverified, suspicious or unlikely is not a contradiction.\n- A person or object cannot be in two places at once when the evidence says the places are separate.\n- Records, logs and lists are complete only if the evidence says they are.\n- "Between 8:00 AM and 9:00 AM" includes both endpoints. "After noon" does not include noon itself.\n- Read words such as only, nobody, exactly, at least and whenever literally, and work out times, dates, weekdays, counts, durations, speeds, distances, rates, weights, ages and rotas exactly.\n- The answer is the sender of the contradicting message, even if the message is about someone else.\n- Questions and opinions are never the answer."""\n\n\ndef build_prompt(case):\n    speakers = "; ".join(f"{k} = {v}" for k, v in case.speakers.items())\n    chat = "\\n".join(f"{m.num}. {m.label} ({case.speakers[m.label]}): {m.text}" for m in case.messages)\n    return (\n        f"{RULES}\\n\\nScenario: {case.scenario}\\nSpeakers: {speakers}\\nEvidence: {case.evidence}\\n\\nChat:\\n{chat}\\n\\n"\n        "Check every claim in the chat one at a time against the evidence. "\n        "Then end your reply with one final line of the form:\\nANSWER: <letter>"\n    )\n', 'lc/llm/judge_vllm.py': '"""Thinking-mode LLM judge: batched offline vLLM inference over a split, one JSON line per case.\n\nResumable: ids already in --out are skipped. A sample that ends without an "ANSWER: <letter>" line\n(usually because it hit --max-tokens) gets one extra greedy token after a forced "ANSWER:".\nExample: LC_DATA_DIR=data python -m lc.llm.judge_vllm --model models/qwen3-8b-awq --ids configs/dev200.txt --out outputs/x.jsonl\n"""\nimport argparse\nimport json\nimport math\nimport os\nimport re\nimport subprocess\nimport time\nfrom collections import Counter\n\n# FlashInfer compiles its sampling kernel at start-up and fails with this server\'s nvcc 11.5; use the PyTorch sampler.\nos.environ.setdefault("VLLM_USE_FLASHINFER_SAMPLER", "0")\nfrom vllm import LLM, SamplingParams  # noqa: E402\nfrom vllm.sampling_params import RequestOutputKind  # noqa: E402\n\nfrom lc.data import load  # noqa: E402\nfrom lc.llm.prompt import build_prompt  # noqa: E402\n\nLETTERS = "ABCD"\nANSWER_RE = re.compile(r"ANSWER\\W{0,6}([ABCD])\\b")\nNUM_LOGPROBS = 20  # vLLM\'s default cap; enough to see all four letters at the answer position\n\n\ndef free_gpu_util():\n    """Leaves 1.5 GiB of the card free for its other users. vLLM\'s sampler takes about 0.4 GiB beyond the\n    gpu_memory_utilization budget (top-p sorting is not in its memory profile), so 1.9 GiB is held back."""\n    free_mib = int(subprocess.check_output(["nvidia-smi", "--query-gpu=memory.free", "--format=csv,noheader,nounits"]).split()[0])\n    return round((free_mib / 1024 - 1.9) / 48, 3)\n\n\ndef letter_probs(logprobs_at):\n    """Probability of each letter in one position\'s top log-probabilities (" B", "B" and "**B" all count as B)."""\n    p = dict.fromkeys(LETTERS, 0.0)\n    for lp in logprobs_at.values():\n        t = (lp.decoded_token or "").strip(" *")\n        if t in p:\n            p[t] += math.exp(lp.logprob)\n    return {k: round(v, 5) for k, v in p.items()}\n\n\ndef read_answer(out):\n    """(letter, letter probabilities at the answer token) from a finished thinking sample, or (None, None)."""\n    if "</think>" not in out.text:\n        return None, None\n    found = ANSWER_RE.findall(out.text.rsplit("</think>", 1)[1])\n    if not found:\n        return None, None\n    toks = [lp[t].decoded_token or "" for t, lp in zip(out.token_ids, out.logprobs)]\n    for i in range(len(toks) - 1, -1, -1):\n        if toks[i].strip(" *") == found[-1] and re.search(r"ANSWER\\W{0,6}$", "".join(toks[max(0, i - 6):i])):\n            return found[-1], letter_probs(out.logprobs[i])\n    return found[-1], None\n\n\ndef complete_lines(path):\n    """Lines of a JSONL file, after cutting off a half-written last line that a killed run can leave."""\n    if not os.path.exists(path):\n        return []\n    with open(path, "rb+") as f:\n        data = f.read()\n        data = data[:data.rfind(b"\\n") + 1]\n        f.truncate(len(data))\n    return [line for line in data.decode().splitlines() if line.strip()]\n\n\ndef vote(samples):\n    counts = Counter(s["letter"] for s in samples if s["letter"])\n    if not counts:\n        return None\n    top = max(counts.values())\n    # ties go to the letter with the larger summed probability at the answer position\n    return max((l for l in counts if counts[l] == top), key=lambda l: sum((s["p"] or {}).get(l, 0) for s in samples))\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    ap.add_argument("--model", required=True, help="local model folder")\n    ap.add_argument("--split", default="train", help="train or test (CSV in LC_DATA_DIR)")\n    ap.add_argument("--ids", help="file with one case id per line, run in that order; default: every case in the split")\n    ap.add_argument("--out", required=True, help="JSONL to append to; reasoning texts go to <out>.texts.jsonl")\n    ap.add_argument("--n", type=int, default=1, help="samples per case, majority vote (self-consistency)")\n    ap.add_argument("--temperature", type=float, default=0.6)\n    ap.add_argument("--top-p", type=float, default=0.95)\n    ap.add_argument("--top-k", type=int, default=20)\n    ap.add_argument("--presence-penalty", type=float, default=0.0)\n    ap.add_argument("--seed", type=int, default=0, help="sample k of every case uses seed + k")\n    ap.add_argument("--max-tokens", type=int, default=8192, help="output tokens per sample, thinking included")\n    ap.add_argument("--max-num-seqs", type=int, default=64)\n    ap.add_argument("--max-num-batched-tokens", type=int, default=4096, help="lower it to free activation memory for the KV cache")\n    ap.add_argument("--gpu-util", type=float, help="fraction of the 48 GB card; default (free GiB - 1.9) / 48 at launch")\n    args = ap.parse_args()\n\n    cases = load(args.split)\n    if args.ids:\n        with open(args.ids) as f:\n            order = dict.fromkeys(f.read().split())\n        by_id = {c.id: c for c in cases}\n        cases = [by_id[i] for i in order]  # file order: vLLM serves requests first come, first served\n    texts_path = args.out[:-len(".jsonl")] + ".texts.jsonl" if args.out.endswith(".jsonl") else args.out + ".texts"\n    done = {json.loads(line)["id"] for line in complete_lines(args.out)}\n    complete_lines(texts_path)\n    todo = [c for c in cases if c.id not in done]\n    print(f"{len(cases)} cases, {len(done)} already in {args.out}, {len(todo)} to run", flush=True)\n    if not todo:\n        return\n\n    util = args.gpu_util or free_gpu_util()\n    with open(os.path.join(args.model, "config.json")) as f:\n        multimodal = "vision_config" in json.load(f)\n    print(f"gpu_memory_utilization {util}", flush=True)\n    llm = LLM(args.model, gpu_memory_utilization=util, max_model_len=args.max_tokens + 2048, max_num_seqs=args.max_num_seqs,\n              max_num_batched_tokens=args.max_num_batched_tokens, seed=args.seed, **({"language_model_only": True} if multimodal else {}))\n    print(subprocess.run(["nvidia-smi", "--query-compute-apps=pid,used_memory", "--format=csv,noheader"],\n                         capture_output=True, text=True).stdout, flush=True)\n\n    tok = llm.get_tokenizer()\n    eng = llm.llm_engine\n    final = RequestOutputKind.FINAL_ONLY\n    sample_params = SamplingParams(n=args.n, temperature=args.temperature, top_p=args.top_p, top_k=args.top_k,\n                                   presence_penalty=args.presence_penalty, seed=args.seed, max_tokens=args.max_tokens,\n                                   logprobs=NUM_LOGPROBS, output_kind=final)\n    force_params = SamplingParams(max_tokens=1, temperature=0.0, logprobs=NUM_LOGPROBS, output_kind=final)\n    prompts = {}\n    for c in todo:\n        prompts[c.id] = tok.apply_chat_template([{"role": "user", "content": build_prompt(c)}], tokenize=False,\n                                                add_generation_prompt=True, enable_thinking=True)\n        eng.add_request(c.id, prompts[c.id], sample_params)\n\n    pending, waiting, prompt_tokens = {}, Counter(), {}\n    t0, n_written, tokens_written = time.time(), 0, 0\n    with open(args.out, "a") as fout, open(texts_path, "a") as ftxt:\n        while eng.has_unfinished_requests():\n            for o in eng.step():\n                if not o.finished:\n                    continue\n                cid, _, k = o.request_id.partition("#force")\n                if k:\n                    p = letter_probs(o.outputs[0].logprobs[0])\n                    pending[cid][int(k)].update(letter=max(p, key=p.get) if any(p.values()) else None, p=p, forced=True)\n                    waiting[cid] -= 1\n                else:\n                    prompt_tokens[cid] = len(o.prompt_token_ids)\n                    pending[cid] = []\n                    for out in sorted(o.outputs, key=lambda x: x.index):\n                        letter, p = read_answer(out)\n                        pending[cid].append({"letter": letter, "p": p, "tokens": len(out.token_ids), "forced": False, "text": out.text})\n                        if letter is None:\n                            suffix = "\\n\\nANSWER:" if "</think>" in out.text else "\\n</think>\\n\\nANSWER:"\n                            eng.add_request(f"{cid}#force{out.index}", prompts[cid] + out.text + suffix, force_params)\n                            waiting[cid] += 1\n                if waiting[cid]:\n                    continue\n                s = pending.pop(cid)\n                ps = [x["p"] for x in s if x["p"]]\n                fout.write(json.dumps({\n                    "id": cid, "pred": vote(s), "letters": [x["letter"] for x in s], "probs": [x["p"] for x in s],\n                    "p_mean": {l: round(sum(p[l] for p in ps) / len(ps), 5) for l in LETTERS} if ps else None,\n                    "out_tokens": [x["tokens"] for x in s], "forced": [x["forced"] for x in s], "prompt_tokens": prompt_tokens.pop(cid),\n                }) + "\\n")\n                ftxt.write(json.dumps({"id": cid, "texts": [x["text"] for x in s]}) + "\\n")\n                fout.flush()\n                ftxt.flush()\n                n_written += 1\n                tokens_written += sum(x["tokens"] for x in s)\n                if n_written % 25 == 0 or n_written == len(todo):\n                    mins = (time.time() - t0) / 60\n                    print(f"{n_written}/{len(todo)} cases, {mins:.1f} min, {n_written / mins:.2f} cases/min, "\n                          f"{tokens_written / n_written:.0f} output tokens/case, {tokens_written / mins / 60:.0f} tokens/s", flush=True)\n\n\nif __name__ == "__main__":  # vLLM\'s engine runs in a spawned process that re-imports this module\n    main()\n', 'kjudge.py': '"""The thinking-mode judge of lc/llm/judge_vllm.py (same prompt, sampling and answer parsing) for a Kaggle session\nwith two T4 cards: tensor parallel over both cards, float16, and phases run one after another in one engine.\n\nA phase is split:ids_file:out_jsonl[:min_accuracy]. A train phase also saves reasoning texts and, given\nmin_accuracy, stops the run when its accuracy is lower. Cases already in out_jsonl are skipped. No new case is\nwaited for after --deadline (unix time). Every case is one flushed JSON line with judge_vllm\'s fields.\nExample: python -m kjudge --model /tmp/models/m --phase train:dev.txt:dev.jsonl:0.85 --phase test:t.txt:test.jsonl\n"""\nimport argparse\nimport json\nimport os\nimport subprocess\nimport time\nfrom collections import Counter\n\nfrom lc.data import load\nfrom lc.llm.judge_vllm import LETTERS, NUM_LOGPROBS, letter_probs, read_answer, vote  # also turns off the FlashInfer sampler\nfrom lc.llm.prompt import build_prompt\nfrom vllm import LLM, SamplingParams\nfrom vllm.sampling_params import RequestOutputKind\n\nHEARTBEAT = "heartbeat"  # touched after start-up and after every case, for the launcher\'s hang check\n\n\ndef beat():\n    with open(HEARTBEAT, "w") as f:\n        f.write(str(time.time()))\n\n\ndef gpus():\n    q = "index,name,memory.used,memory.total,temperature.gpu,clocks.sm,power.draw"\n    return subprocess.run(["nvidia-smi", f"--query-gpu={q}", "--format=csv,noheader"], capture_output=True, text=True).stdout\n\n\ndef scores(out_path, cases):\n    """(correct, labelled, forced answers, mean output tokens) over the cases\' lines in out_path."""\n    want = {c.id: c.label for c in cases}\n    rows = [r for r in map(json.loads, open(out_path)) if r["id"] in want]\n    correct = sum(r["pred"] == want[r["id"]] for r in rows)\n    forced = sum(any(r["forced"]) for r in rows)\n    return correct, len(rows), forced, sum(sum(r["out_tokens"]) for r in rows) / max(len(rows), 1)\n\n\ndef run_phase(eng, tok, name, cases, out_path, keep_texts, sample_params, force_params, deadline):\n    """Runs the cases not yet in out_path until all finish or the deadline passes; True if the deadline passed."""\n    done = set()\n    if os.path.exists(out_path):\n        with open(out_path) as f:\n            done = {json.loads(line)["id"] for line in f if line.strip()}\n    todo = [c for c in cases if c.id not in done]\n    label = {c.id: c.label for c in todo}\n    print(f"[{name}] {len(cases)} cases, {len(done & {c.id for c in cases})} already in {out_path}, {len(todo)} to run", flush=True)\n    prompts = {}\n    for c in todo:\n        prompts[c.id] = tok.apply_chat_template([{"role": "user", "content": build_prompt(c)}], tokenize=False,\n                                                add_generation_prompt=True, enable_thinking=True)\n        eng.add_request(c.id, prompts[c.id], sample_params)\n\n    pending, waiting, prompt_tokens = {}, Counter(), {}\n    t0, n_written, tokens_written, correct = time.time(), 0, 0, 0\n    texts_path = out_path[:-len(".jsonl")] + ".texts.jsonl"\n    with open(out_path, "a") as fout, open(texts_path if keep_texts else os.devnull, "a") as ftxt:\n        while eng.has_unfinished_requests():\n            if time.time() > deadline:\n                print(f"[{name}] deadline reached after {n_written} of {len(todo)} cases", flush=True)\n                return True\n            for o in eng.step():\n                if not o.finished:\n                    continue\n                cid, _, k = o.request_id.partition("#force")\n                if k:\n                    p = letter_probs(o.outputs[0].logprobs[0])\n                    pending[cid][int(k)].update(letter=max(p, key=p.get) if any(p.values()) else None, p=p, forced=True)\n                    waiting[cid] -= 1\n                else:\n                    prompt_tokens[cid] = len(o.prompt_token_ids)\n                    pending[cid] = []\n                    for out in sorted(o.outputs, key=lambda x: x.index):\n                        letter, p = read_answer(out)\n                        pending[cid].append({"letter": letter, "p": p, "tokens": len(out.token_ids), "forced": False, "text": out.text})\n                        if letter is None:\n                            suffix = "\\n\\nANSWER:" if "</think>" in out.text else "\\n</think>\\n\\nANSWER:"\n                            eng.add_request(f"{cid}#force{out.index}", prompts[cid] + out.text + suffix, force_params)\n                            waiting[cid] += 1\n                if waiting[cid]:\n                    continue\n                s = pending.pop(cid)\n                ps = [x["p"] for x in s if x["p"]]\n                pred = vote(s)\n                fout.write(json.dumps({\n                    "id": cid, "pred": pred, "letters": [x["letter"] for x in s], "probs": [x["p"] for x in s],\n                    "p_mean": {l: round(sum(p[l] for p in ps) / len(ps), 5) for l in LETTERS} if ps else None,\n                    "out_tokens": [x["tokens"] for x in s], "forced": [x["forced"] for x in s], "prompt_tokens": prompt_tokens.pop(cid),\n                }) + "\\n")\n                ftxt.write(json.dumps({"id": cid, "texts": [x["text"] for x in s]}) + "\\n")\n                fout.flush()\n                ftxt.flush()\n                beat()\n                n_written += 1\n                tokens_written += sum(x["tokens"] for x in s)\n                correct += label[cid] is not None and pred == label[cid]\n                if n_written % 25 == 0 or n_written == len(todo):\n                    mins = (time.time() - t0) / 60\n                    acc = f", {correct}/{n_written} correct" if label[cid] is not None else ""\n                    print(f"[{name}] {n_written}/{len(todo)} cases, {mins:.1f} min, {n_written / mins:.2f} cases/min, "\n                          f"{tokens_written / n_written:.0f} output tokens/case, {tokens_written / mins / 60:.0f} tokens/s{acc}", flush=True)\n    return False\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    ap.add_argument("--model", required=True, help="local model folder")\n    ap.add_argument("--phase", action="append", required=True, help="split:ids_file:out_jsonl[:min_accuracy], run in order")\n    ap.add_argument("--deadline", type=float, default=float("inf"), help="unix time; no case is waited for after it")\n    ap.add_argument("--tp", type=int, default=2, help="tensor parallel size (number of cards)")\n    ap.add_argument("--eager", action="store_true", help="no torch.compile and no CUDA graphs")\n    ap.add_argument("--n", type=int, default=1, help="samples per case, majority vote")\n    ap.add_argument("--temperature", type=float, default=0.6)\n    ap.add_argument("--top-p", type=float, default=0.95)\n    ap.add_argument("--top-k", type=int, default=20)\n    ap.add_argument("--presence-penalty", type=float, default=0.0)\n    ap.add_argument("--seed", type=int, default=0)\n    ap.add_argument("--max-tokens", type=int, default=6000, help="output tokens per sample, thinking included")\n    ap.add_argument("--max-num-seqs", type=int, default=32)\n    ap.add_argument("--max-num-batched-tokens", type=int, default=4096)\n    ap.add_argument("--gpu-util", type=float, default=0.92, help="fraction of each card\'s memory for vLLM")\n    args = ap.parse_args()\n\n    phases = []\n    splits = {}\n    for spec in args.phase:\n        split, ids_path, out_path, *gate = spec.split(":")\n        if split not in splits:\n            splits[split] = {c.id: c for c in load(split)}\n        with open(ids_path) as f:\n            ids = list(dict.fromkeys(f.read().split()))\n        phases.append((f"{split}:{os.path.basename(ids_path)}", [splits[split][i] for i in ids], out_path, float(gate[0]) if gate else None))\n    print(gpus(), flush=True)\n\n    llm = LLM(args.model, tensor_parallel_size=args.tp, dtype="float16", gpu_memory_utilization=args.gpu_util,\n              max_model_len=args.max_tokens + 2048, max_num_seqs=args.max_num_seqs, max_num_batched_tokens=args.max_num_batched_tokens,\n              seed=args.seed, disable_custom_all_reduce=True, enforce_eager=args.eager)\n    beat()\n    print(gpus(), flush=True)\n    tok = llm.get_tokenizer()\n    final = RequestOutputKind.FINAL_ONLY\n    sample_params = SamplingParams(n=args.n, temperature=args.temperature, top_p=args.top_p, top_k=args.top_k,\n                                   presence_penalty=args.presence_penalty, seed=args.seed, max_tokens=args.max_tokens,\n                                   logprobs=NUM_LOGPROBS, output_kind=final)\n    force_params = SamplingParams(max_tokens=1, temperature=0.0, logprobs=NUM_LOGPROBS, output_kind=final)\n\n    for name, cases, out_path, gate in phases:\n        is_train = cases[0].label is not None\n        late = run_phase(llm.llm_engine, tok, name, cases, out_path, is_train, sample_params, force_params, args.deadline)\n        print(gpus(), flush=True)\n        if is_train:\n            correct, n, forced, mean_tokens = scores(out_path, cases)\n            print(f"[{name}] accuracy {correct}/{n} = {correct / max(n, 1):.4f}, {forced} forced answers, "\n                  f"{mean_tokens:.0f} output tokens/case", flush=True)\n            if gate is not None and correct < gate * len(cases):\n                print(f"[{name}] below the {gate} accuracy gate: stopping", flush=True)\n                break\n        if late:\n            break\n    os._exit(0)  # every line is flushed; do not wait for the engine\'s processes to wind down\n\n\nif __name__ == "__main__":  # vLLM starts its workers in spawned processes, which re-import this module\n    main()\n'}

# Body of run.py (build.py puts CFG and FILES above it). Runs inside a Kaggle session: installs the GPU server's
# vLLM build in a fresh Python 3.12 environment, downloads the model at a pinned revision, writes the judge package
# to /tmp/lc_src and runs it over the embedded id lists, retrying with safer engine settings if an attempt fails.
import glob
import os
import signal
import subprocess
import time

T0 = time.time()
SRC = "/tmp/lc_src"
PY = "/tmp/venv/bin/python"
# Same vLLM build and pins as scripts/server/setup_env.sh on the GPU server.
INSTALL = ("https://github.com/vllm-project/vllm/releases/download/v0.32.0/vllm-0.32.0+cu129-cp38-abi3-manylinux_2_28_x86_64.whl "
           "torchcodec==0.16.0+cu129 --extra-index-url https://download.pytorch.org/whl/cu129 --index-strategy unsafe-best-match")
ATTEMPTS = [  # (extra judge arguments, extra environment), tried in order until one exits cleanly
    ("", {}),
    ("--eager", {}),
    ("--eager", {"VLLM_USE_TRITON_AWQ": "1", "VLLM_ATTENTION_BACKEND": "TRITON_ATTN"}),
]
START_LIMIT, STALL_LIMIT = 25 * 60, 45 * 60  # seconds without a heartbeat before an attempt counts as hung


def log(msg):
    print(f"[{(time.time() - T0) / 60:6.1f} min] {msg}", flush=True)


def sh(cmd):
    log(f"$ {cmd}")
    subprocess.run(cmd, shell=True, check=True)


def run_judge(cmd, env):
    """Runs one judge attempt and returns its exit code; kills it when its heartbeat file goes stale."""
    hb = os.path.join(SRC, "heartbeat")
    if os.path.exists(hb):
        os.remove(hb)
    log(f"$ {cmd}")
    p = subprocess.Popen(cmd, shell=True, cwd=SRC, env=env, start_new_session=True)
    start = time.time()
    while p.poll() is None:
        time.sleep(20)
        stale = time.time() - (os.path.getmtime(hb) if os.path.exists(hb) else start)
        if stale > (STALL_LIMIT if os.path.exists(hb) else START_LIMIT):
            log(f"no heartbeat for {stale / 60:.0f} min: killing the attempt")
            os.killpg(p.pid, signal.SIGKILL)
            p.wait()
    return p.returncode


def main():
    for rel, text in FILES.items():
        path = os.path.join(SRC, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(text)
    phases = []
    for i, (split, ids, out, gate) in enumerate(CFG["phases"]):
        with open(f"{SRC}/phase{i}.txt", "w") as f:
            f.write("\n".join(ids) + "\n")
        phases.append(f"--phase {split}:{SRC}/phase{i}.txt:/kaggle/working/{out}" + (f":{gate}" if gate else ""))
        log(f"phase {i}: {split}, {len(ids)} ids -> {out}" + (f", accuracy gate {gate}" if gate else ""))
    sh("nvidia-smi --query-gpu=index,name,memory.total,driver_version --format=csv; nproc; free -g | head -2; df -h /dev/shm /tmp")
    sh("uv venv /tmp/venv --python 3.12")
    sh(f"uv pip install --python {PY} {INSTALL}")
    sh(f"{PY} -c 'import torch, vllm, transformers; print(torch.__version__, torch.version.cuda, torch.cuda.device_count(), "
       f"vllm.__version__, transformers.__version__)'")
    m = CFG["model"]
    sh(f"HF_HUB_DISABLE_PROGRESS_BARS=1 HF_XET_HIGH_PERFORMANCE=1 {PY} -c 'from huggingface_hub import snapshot_download; "
       f"snapshot_download(\"{m['repo']}\", revision=\"{m['revision']}\", local_dir=\"/tmp/models/{m['name']}\")' "
       f"&& du -sh /tmp/models/{m['name']}")
    data_dir = os.path.dirname(glob.glob("/kaggle/input/**/train.csv", recursive=True)[0])
    deadline = T0 + CFG["budget_hours"] * 3600
    base = f"{PY} -m kjudge --model /tmp/models/{m['name']} {' '.join(phases)} --deadline {deadline:.0f} {CFG['judge_args']}"
    # Kaggle's PYTHONPATH points at its own Python 3.13 packages, which must not leak into the 3.12 environment.
    env = {k: v for k, v in os.environ.items() if k != "PYTHONPATH"}
    for extra_args, extra_env in ATTEMPTS:
        rc = run_judge(f"{base} {extra_args}", dict(env, LC_DATA_DIR=data_dir, **extra_env))
        log(f"judge exited with code {rc}")
        if rc == 0 or time.time() > deadline:
            break
    sh("ls -la /kaggle/working; wc -l /kaggle/working/*.jsonl || true")


main()
